import React, { useState, useMemo, useCallback } from 'react';
import { Link } from 'react-router-dom'; 
// Se mantienen las importaciones que no son usadas por convención, pero Link y useLocation se pueden eliminar.
// import { Link, useLocation } from 'react-router-dom'; 

import Header_c from "../../components/Header_c"; 
import "../../components/general.css"; // Archivo CSS sugerido

export default function PerfilFormSinSidebar() {
    return (  
        // Se elimina el div principal "dashboard-layout" y solo queda el contenedor principal del contenido.
        <main className="contenido">
            <Header_c />

            <form className="form-cambiar">
                    <div className="subtitulo">
                        <h2>Cambiar contraseña</h2>
                    </div>

                    {/* Nueva Contraseña */}
                    <label htmlFor="nueva">Nueva contraseña</label>
                    <input 
                        type="password" 
                        id="nueva" 
                        name="nueva" // Agregado el atributo name por buena práctica
                        placeholder="Ingresa tu nueva contraseña" 
                    />

                    {/* Confirmar Contraseña */}
                    <label htmlFor="confirmar">Confirmar contraseña</label>
                    <input 
                        type="password" 
                        id="confirmar" 
                        name="confirmar" // Agregado el atributo name
                        placeholder="Confirma tu nueva contraseña" 
                    />

                    {/* Botón Guardar Cambios */}
                    <button 
                        type="submit" // Usar 'submit' si el formulario debe enviarse
                        className="btn-guardarc" // Agregué una clase para estilizar
                        onClick={handleGuardarClick} 
                    >
                        Guardar cambios
                    </button>
                </form>
        </main>
    );
}
